public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Sends a draft for a being generated text message; for bots only
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SendTextMessageDraftAsync(long chatId = default, int forumTopicId = default, long draftId = default, FormattedText text = default)
    {

           using var activity =  StartCallActivity("SendTextMessageDraftAsync", typeof(SendTextMessageDraft).FullName ?? "SendTextMessageDraftAsync");

           try
           {
             return client.SendTextMessageDraftAsync(chatId, forumTopicId, draftId, text);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
